import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8095/#/pages/inspection/index?kind=post',{waitUntil:'domcontentloaded',timeout:25000}).catch(()=>{})
await pg.waitForTimeout(2500)
const info=await pg.evaluate(()=>{
  const cb=document.querySelector('.choice-b')
  const remark=[...document.querySelectorAll('.field-block-label')].find(e=>e.textContent.trim()==='备注')
  function full(el,name){ if(!el)return null; const cs=getComputedStyle(el); return {name, tag:el.tagName, cls:el.className, fs:cs.fontSize, fw:cs.fontWeight, color:cs.color, ff:cs.fontFamily.replace(/"/g,'').slice(0,40), opacity:cs.opacity, letterSpacing:cs.letterSpacing} }
  // also check the parent .choice-label color / any inherited
  return { choiceB: full(cb,'choiceB'), remark: full(remark,'remark'),
    choiceLabelColor: cb?getComputedStyle(cb.parentElement).color:null,
    choiceParentHTML: cb?cb.parentElement.outerHTML.slice(0,200):null }
})
console.log(JSON.stringify(info,null,2))
await b.close()

