const info=await pg.evaluate(()=>{
  const cbSpan=document.querySelector('.choice-b span')
  const rmSpan=document.querySelector('.field-block-label span')
  // also grab the first field-block-label (备注) span
  const remark=[...document.querySelectorAll('.field-block-label')].find(e=>e.textContent.trim()==='备注')
  const rmSpan2=remark?remark.querySelector('span'):null
  function f(el){if(!el)return null;const cs=getComputedStyle(el);return{tag:el.tagName,fs:cs.fontSize,fw:cs.fontWeight,color:cs.color,ff:cs.fontFamily.replace(/"/g,'').slice(0,30)}}
  return {choiceBspan:f(cbSpan), remarkSpan:f(rmSpan2), firstFblSpan:f(rmSpan)}
})
console.log(JSON.stringify(info,null,2))
await b.close()

